class Solution {
    public int kthFactor(int n, int k) {
        List<Integer> small = new ArrayList<>(), large = new ArrayList<>();
        for (int i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                small.add(i);
                if (i != n / i) large.add(n / i);
            }
        }
        Collections.reverse(large);
        small.addAll(large);
        return k <= small.size() ? small.get(k - 1) : -1;
    }
}

